constructor(text) {
        this.text = text;
        this.a = [];
        this.b = [];
        this.a.push(0);
        for (let i = 0; i < text.length; i++) {
            if (text.charAt(i) === '\n') {
                this.a.push(i + 1);
                if (i > 0 && text.charAt(i - 1) === '\r') {
                    this.b.push(i - 1);
                }
                else {
                    this.b.push(i);
                }
            }
        }
        this.b.push(text.length);
    }
